import { QueryClientProvider } from "@tanstack/react-query";
import { DarkTheme, DefaultTheme, ThemeProvider } from "expo-router";
import { Stack, useRouter, useSegments } from "expo-router";
import * as SplashScreen from "expo-splash-screen";
import { useEffect } from "react";
import { useColorScheme } from "react-native";

import { AnimatedSplashOverlay } from "@/components/animated-icon";
import { authClient } from "@/lib/auth-client";
import { queryClient } from "@/lib/query-client";
import { TRPCProvider, trpcClient } from "@/lib/trpc";

SplashScreen.preventAutoHideAsync();

function useProtectedRoute(session: { userId: string } | null, isPending: boolean) {
	const segments = useSegments();
	const router = useRouter();

	useEffect(() => {
		if (isPending) return;

		const isAuthScreen = segments[0] === "sign-in" || segments[0] === "sign-up";

		if (!session && !isAuthScreen) {
			router.replace("/sign-in");
		} else if (session && isAuthScreen) {
			router.replace("/");
		}
	}, [session, segments, isPending, router]);
}

export default function RootLayout() {
	const colorScheme = useColorScheme();
	const { data, isPending } = authClient.useSession();
	const session = data?.session ?? null;

	useProtectedRoute(session, isPending);

	return (
		<ThemeProvider value={colorScheme === "dark" ? DarkTheme : DefaultTheme}>
			<TRPCProvider trpcClient={trpcClient} queryClient={queryClient}>
				<QueryClientProvider client={queryClient}>
					<AnimatedSplashOverlay />
					<Stack screenOptions={{ headerShown: false }}>
						<Stack.Screen name="(drawer)" />
						<Stack.Screen name="sign-in" />
						<Stack.Screen name="sign-up" />
						<Stack.Screen name="profile" options={{ headerShown: true, title: "Profile" }} />
					</Stack>
				</QueryClientProvider>
			</TRPCProvider>
		</ThemeProvider>
	);
}

/**
 * Below are the colors that are used in the app. The colors are defined in the light and dark mode.
 * There are many other ways to style your app. For example, [Nativewind](https://www.nativewind.dev/), [Tamagui](https://tamagui.dev/), [unistyles](https://reactnativeunistyles.vercel.app), etc.
 */

import "@/global.css";

import { Platform } from "react-native";

export const Colors = {
	light: {
		text: "#000000",
		background: "#ffffff",
		backgroundElement: "#F0F0F3",
		backgroundSelected: "#E0E1E6",
		textSecondary: "#60646C",
		primary: "#7c3aed",
		primaryForeground: "#ffffff",
		border: "#E4E4E7",
		destructive: "#dc2626",
		card: "#ffffff",
		mutedForeground: "#71717a",
	},
	dark: {
		text: "#ffffff",
		background: "#000000",
		backgroundElement: "#212225",
		backgroundSelected: "#2E3135",
		textSecondary: "#B0B4BA",
		primary: "#8b5cf6",
		primaryForeground: "#ffffff",
		border: "rgba(255, 255, 255, 0.1)",
		destructive: "#f87171",
		card: "#202023",
		mutedForeground: "#a1a1aa",
	},
} as const;

export type ThemeColor = keyof typeof Colors.light & keyof typeof Colors.dark;

export const Fonts = Platform.select({
	ios: {
		/** iOS `UIFontDescriptorSystemDesignDefault` */
		sans: "system-ui",
		/** iOS `UIFontDescriptorSystemDesignSerif` */
		serif: "ui-serif",
		/** iOS `UIFontDescriptorSystemDesignRounded` */
		rounded: "ui-rounded",
		/** iOS `UIFontDescriptorSystemDesignMonospaced` */
		mono: "ui-monospace",
	},
	default: {
		sans: "normal",
		serif: "serif",
		rounded: "normal",
		mono: "monospace",
	},
	web: {
		sans: "var(--font-display)",
		serif: "var(--font-serif)",
		rounded: "var(--font-rounded)",
		mono: "var(--font-mono)",
	},
});

export const Spacing = {
	half: 2,
	one: 4,
	two: 8,
	three: 16,
	four: 24,
	five: 32,
	six: 64,
} as const;

export const BottomTabInset = Platform.select({ ios: 50, android: 80 }) ?? 0;
export const MaxContentWidth = 800;

